 g=groups[(groups.ForecastLevel==level)&groups.Model.eq(model)&groups.GroupType.eq('Location')];notes+=f'### {level}: {model}\n\n'+table(g,['Location','Observations','MAE','RMSE','WAPE','P90AbsoluteError'])+'\n\n'
